  {sec:"SQL (T-SQL)",lvl:"III",k:"s-having-count",q:"'GROUP BY cliente HAVING COUNT(*) > 5' devolve:",opts:["Todos os clientes.","Clientes com mais de 5 pedidos.","Os 5 primeiros.","Clientes sem pedidos."],c:1,e:"Filtra grupos: clientes cujo total de pedidos é superior a 5."},

  /* ============ R & Estatística ============ */
  {sec:"R & Estatística",lvl:"I",k:"r-def",q:"O R é:",opts:["Uma folha de cálculo.","Uma linguagem e ambiente estatístico para análise de dados.","Um sistema operativo.","Uma base de dados."],c:1,e:"O R é uma linguagem/ambiente com foco estatístico nativo."},
  {sec:"R & Estatística",lvl:"I",k:"r-custo",q:"Quanto ao licenciamento, o R é:",opts:["Pago e proprietário.","Gratuito e open source (GNU).","Só para empresas grandes.","Exclusivo da Microsoft."],c:1,e:"O R é 100% gratuito e open source, ideal para orçamentos baixos."},
  {sec:"R & Estatística",lvl:"I",k:"r-ggplot",q:"Que biblioteca do R é muito usada para visualizações?",opts:["ggplot2.","pandas.","numpy.","Excel."],c:0,e:"O ggplot2 é a biblioteca de visualização mais conhecida do R."},
  {sec:"R & Estatística",lvl:"I",k:"r-ide",q:"Uma ferramenta/IDE associada ao R é:",opts:["RStudio (Posit).","Photoshop.","Power Point.","Outlook."],c:0,e:"O RStudio (Posit) é o ambiente de desenvolvimento típico do R (versão desktop gratuita)."},
  {sec:"R & Estatística",lvl:"II",k:"r-eda",q:"O que é a EDA (Exploratory Data Analysis)?",opts:["Publicar relatórios.","Etapa de exploração para entender dados, detetar padrões e problemas (missing, outliers).","Encriptar dados.","Fazer backup."],c:1,e:"A EDA explora os dados: padrões, valores em falta, outliers e geração de hipóteses."},
  {sec:"R & Estatística",lvl:"II",k:"r-nulos",q:"Em R, para ver valores ausentes por coluna pode usar-se:",opts:["colSums(is.na(dados)).","mean(dados).","plot(dados).","library(dados)."],c:0,e:"colSums(is.na(dados)) conta os valores ausentes por coluna."},
  {sec:"R & Estatística",lvl:"II",k:"r-estrutura",q:"Em R, para ver a estrutura/resumo dos dados usa-se:",opts:["str() e summary().","hist().","cor().","INSERT."],c:0,e:"str() mostra a estrutura e summary() um resumo estatístico."},
  {sec:"R & Estatística",lvl:"II",k:"r-cor",q:"Em R, cor(x, y) calcula:",opts:["A média.","A correlação entre variáveis.","O histograma.","O desvio padrão."],c:1,e:"cor() ajuda a entender a relação (correlação) entre variáveis."},
  {sec:"R & Estatística",lvl:"I",k:"e-media",q:"A média (mean) representa:",opts:["O valor mais comum.","O valor médio (soma dividida pelo número de observações).","O valor do meio.","O maior valor."],c:1,e:"A média é a soma dos valores a dividir pelo nº de observações."},
  {sec:"R & Estatística",lvl:"I",k:"e-mediana",q:"A mediana é:",opts:["A soma dos valores.","O valor do meio quando os dados estão ordenados.","O valor mais frequente.","O desvio padrão."],c:1,e:"A mediana é o valor central dos dados ordenados."},
  {sec:"R & Estatística",lvl:"I",k:"e-moda",q:"A moda é:",opts:["O valor que mais se repete.","O valor do meio.","A média.","O maior valor."],c:0,e:"A moda é o valor mais frequente (ex.: produto mais vendido)."},
  {sec:"R & Estatística",lvl:"II",k:"e-outliers",q:"Quando existem valores extremos (outliers), qual medida costuma ser mais fiável?",opts:["A média.","A mediana.","A soma.","O máximo."],c:1,e:"A mediana é mais robusta a outliers do que a média."},
  {sec:"R & Estatística",lvl:"II",k:"e-quartis",q:"Os quartis dividem os dados ordenados em:",opts:["2 partes.","3 partes.","4 partes iguais (25% cada).","10 partes."],c:2,e:"Q1/Q2/Q3 dividem os dados em quatro partes de 25%."},
  {sec:"R & Estatística",lvl:"II",k:"e-q2",q:"O segundo quartil (Q2) corresponde a:",opts:["Ao mínimo.","À mediana (50%).","Ao máximo.","À moda."],c:1,e:"Q2 é a mediana (50% dos dados abaixo)."},
  {sec:"R & Estatística",lvl:"III",k:"e-q1",q:"Q1 = 25% significa que:",opts:["25% dos dados estão acima desse valor.","25% dos dados estão abaixo desse valor.","É a média.","É o valor mais comum."],c:1,e:"Q1 é o valor abaixo do qual estão 25% dos dados."},
  {sec:"R & Estatística",lvl:"III",k:"e-media-cuidado",q:"Um cuidado ao usar a média é que:",opts:["Nunca engana.","Valores muito altos/baixos (outliers) podem distorcê-la.","É sempre igual à moda.","Não se pode calcular."],c:1,e:"A média é sensível a valores extremos, podendo enganar."},
  {sec:"R & Estatística",lvl:"III",k:"e-desvio",q:"O desvio padrão (sd) mede:",opts:["O valor central.","A dispersão dos dados em torno da média.","O nº de registos.","A correlação."],c:1,e:"O desvio padrão indica quão dispersos os dados estão relativamente à média."},
  {sec:"R & Estatística",lvl:"III",k:"e-porque",q:"Porque é importante a estatística na análise de dados?",opts:["Só para gráficos.","Para resumir dados, identificar padrões e apoiar decisões, evitando interpretações erradas.","Para encriptar dados.","Não é importante."],c:1,e:"A estatística resume grandes volumes, revela padrões e apoia decisões."},

  /* ============ Power BI — Fundamentos & Instalação ============ */
  {sec:"Power BI — Fundamentos & Instalação",lvl:"I",k:"p-oque",q:"O Power BI é uma ferramenta da Microsoft para:",opts:["Editar imagens.","Transformar dados brutos em insights visuais e interativos.","Enviar e-mails.","Programar jogos."],c:1,e:"O Power BI transforma dados em relatórios e dashboards interativos."},
  {sec:"Power BI — Fundamentos & Instalação",lvl:"I",k:"p-comp",q:"Os três componentes principais do Power BI são:",opts:["Desktop, Service e Mobile.","Excel, Word e Access.","Server, Cloud e Local.","Editor, Viewer e Admin."],c:0,e:"Power BI Desktop (criação), Service (nuvem) e Mobile (móvel)."},
  {sec:"Power BI — Fundamentos & Instalação",lvl:"I",k:"p-mobile",q:"Que componente permite aceder a relatórios em telemóveis/tablets?",opts:["Power BI Desktop.","Power BI Mobile.","Power Query.","Report Builder."],c:1,e:"O Power BI Mobile é a versão para dispositivos móveis."},
  {sec:"Power BI — Fundamentos & Instalação",lvl:"I",k:"p-os",q:"O Power BI Desktop funciona em:",opts:["macOS apenas.","Linux apenas.","Windows (exclusivamente).","Qualquer sistema via app nativa."],c:2,e:"O Desktop funciona exclusivamente em Windows; os relatórios veem-se via web no Service."},
  {sec:"Power BI — Fundamentos & Instalação",lvl:"II",k:"p-ram",q:"A RAM recomendada para o Power BI Desktop é:",opts:["1 GB.","2 GB.","8 GB ou mais.","512 MB."],c:2,e:"Mínimo 4 GB, recomendado 8 GB ou mais (16 GB para grandes volumes)."},
  {sec:"Power BI — Fundamentos & Instalação",lvl:"II",k:"p-net",q:"Que requisito de software o Power BI Desktop exige?",opts:[".NET Framework 4.8 ou superior.","Java 8.","Python 3.","PHP."],c:0,e:"Requer .NET Framework 4.8+ (normalmente já incluído no Windows 10/11)."},
  {sec:"Power BI — Fundamentos & Instalação",lvl:"II",k:"p-resol",q:"A resolução mínima recomendada é:",opts:["800x600.","1024x768.","1440x900.","3840x2160."],c:2,e:"O mínimo recomendado é 1440x900 pixels."},
  {sec:"Power BI — Fundamentos & Instalação",lvl:"II",k:"p-disco",q:"O espaço mínimo em disco recomendado é:",opts:["100 MB.","2 GB.","50 GB.","500 GB."],c:1,e:"Mínimo 2 GB para instalação e ficheiros temporários."},
  {sec:"Power BI — Fundamentos & Instalação",lvl:"I",k:"p-gratis",q:"O Power BI Desktop é:",opts:["Pago sempre.","Gratuito para descarregar e usar.","Só via subscrição obrigatória.","Exclusivo de empresas."],c:1,e:"O Power BI Desktop é uma ferramenta gratuita da Microsoft."},
  {sec:"Power BI — Fundamentos & Instalação",lvl:"II",k:"p-internet",q:"Para que é necessária ligação à internet no Power BI Desktop?",opts:["Para criar relatórios offline.","Para publicar no Service e aceder a fontes online.","Nunca é necessária.","Apenas para instalar temas."],c:1,e:"Pode criar offline, mas precisa de internet para publicar e aceder a fontes online."},
  {sec:"Power BI — Fundamentos & Instalação",lvl:"III",k:"p-varejo1",q:"No varejo, um benefício do Power BI é:",opts:["Substituir os vendedores.","Monitorizar vendas em tempo real num painel unificado.","Eliminar o stock.","Imprimir faturas."],c:1,e:"Permite acompanhar vendas em tempo real (lojas e e-commerce)."},
  {sec:"Power BI — Fundamentos & Instalação",lvl:"III",k:"p-varejo2",q:"Ainda no varejo, o Power BI ajuda a:",opts:["Prever tendências/procura e otimizar stock.","Escrever contratos.","Gerir e-mails.","Criar logótipos."],c:0,e:"Ajuda na previsão de tendências, gestão de stock e análise de comportamento do consumidor."},
  {sec:"Power BI — Fundamentos & Instalação",lvl:"III",k:"p-gartner",q:"Segundo o manual, no Quadrante Mágico do Gartner o Power BI é considerado:",opts:["Nicho.","Líder.","Descontinuado.","Irrelevante."],c:1,e:"O Power BI mantém-se como Líder no Quadrante Mágico do Gartner para BI/analytics."},
  {sec:"Power BI — Fundamentos & Instalação",lvl:"I",k:"p-integra",q:"O Power BI integra-se especialmente bem com:",opts:["Ferramentas Microsoft (Excel, Azure, PowerApps).","Apenas com PDFs.","Apenas com imagens.","Nenhuma outra ferramenta."],c:0,e:"Integra-se com Excel, Azure, PowerApps e outras plataformas."},
  {sec:"Power BI — Fundamentos & Instalação",lvl:"II",k:"p-proc",q:"Para grandes volumes de dados, recomenda-se um processador:",opts:["De 1 núcleo antigo.","Multi-núcleo (ex.: Intel Core i7 ou superior).","Sem importância.","Apenas ARM."],c:1,e:"Para muitos dados recomenda-se processador multi-núcleo (i7+) e SSD."},
  {sec:"Power BI — Fundamentos & Instalação",lvl:"I",k:"p-benef",q:"Um benefício-chave do Power BI é:",opts:["Visualização interativa com filtros em tempo real.","Escrever código C.","Editar vídeo.","Gerir redes."],c:0,e:"Oferece visualização interativa, integração de dados, automatização e partilha fácil."},

  /* ============ Power BI — Interface ============ */
  {sec:"Power BI — Interface",lvl:"I",k:"i-visualizacoes",q:"Onde se escolhe o tipo de gráfico de uma visualização?",opts:["No Painel de Visualizações.","No menu Ficheiro.","No Power BI Service.","No painel de Filtros."],c:0,e:"O Painel de Visualizações tem a galeria de gráficos e a formatação."},
  {sec:"Power BI — Interface",lvl:"I",k:"i-campos",q:"O Painel de Campos serve para:",opts:["Instalar visuais.","Selecionar e gerir tabelas/colunas que alimentam as visualizações.","Definir permissões.","Configurar o gateway."],c:1,e:"Mostra todas as tabelas/colunas carregadas, que se arrastam para as visualizações."},
  {sec:"Power BI — Interface",lvl:"I",k:"i-paginas",q:"A Guia de Páginas (abas do relatório) fica:",opts:["Na parte inferior do painel de relatórios.","No topo da janela.","No Service.","No Power Query."],c:0,e:"Fica na parte inferior e permite várias páginas, como abas do Excel."},
  {sec:"Power BI — Interface",lvl:"II",k:"i-ribbon-modeling",q:"Em que guia se criam relacionamentos e medidas DAX?",opts:["Página Inicial.","Inserir.","Modelagem.","Ajuda."],c:2,e:"A guia Modelagem gere tabelas, relacionamentos e medidas/colunas DAX."},
  {sec:"Power BI — Interface",lvl:"II",k:"i-ribbon-inserir",q:"Que guia se usa para inserir visualizações, imagens, textos e formas?",opts:["Inserir.","Ajuda.","Exibição.","Ficheiro."],c:0,e:"A guia Inserir adiciona visuais, imagens, caixas de texto e formas."},
  {sec:"Power BI — Interface",lvl:"II",k:"i-ribbon-home",q:"Na guia 'Página Inicial' encontra-se tipicamente:",opts:["Carregar dados, adicionar medidas e formatar visualizações.","Apenas temas.","Só a ajuda.","Só a publicação."],c:0,e:"A Página Inicial reúne carregar dados, medidas e formatação."},
  {sec:"Power BI — Interface",lvl:"II",k:"i-filtros",q:"Os filtros de RELATÓRIO aplicam-se a:",opts:["Só à página atual.","Todas as páginas do relatório.","Só à visualização selecionada.","Só ao Service."],c:1,e:"Filtro de relatório = todas as páginas; página = atual; visualização = só o visual."},
  {sec:"Power BI — Interface",lvl:"II",k:"i-filtros-pag",q:"Os filtros de PÁGINA aplicam-se a:",opts:["Todas as páginas.","Apenas à página atual.","Apenas ao visual selecionado.","Ao Power Query."],c:1,e:"O filtro de página afeta apenas a página atual."},
  {sec:"Power BI — Interface",lvl:"I",k:"i-slicer",q:"O que é um Slicer (Segmentação de Dados)?",opts:["Uma medida DAX.","Um controlo visual e interativo para filtrar dados.","Uma tabela fato.","Um formato de exportação."],c:1,e:"O slicer permite ao utilizador filtrar visualmente em tempo real."},
  {sec:"Power BI — Interface",lvl:"III",k:"i-slicer-formatos",q:"Um slicer pode ser apresentado como:",opts:["Lista, drop-down ou entre intervalos.","Apenas como gráfico de pizza.","Apenas como tabela.","Apenas como imagem."],c:0,e:"Pode aparecer como lista, drop-down ou entre intervalos (datas/valores)."},
  {sec:"Power BI — Interface",lvl:"II",k:"i-dataview",q:"O Painel de Modelagem de Dados (Data View, ícone de tabela) permite:",opts:["Ver/editar dados em tabela e criar colunas/medidas DAX.","Publicar no Service.","Instalar o gateway.","Criar utilizadores."],c:0,e:"No Data View veem-se os dados e criam-se colunas calculadas e medidas."},
  {sec:"Power BI — Interface",lvl:"II",k:"i-modelview",q:"O Painel de Relacionamentos (Model View, ícone de diagrama) serve para:",opts:["Ver e gerir relacionamentos entre tabelas.","Editar imagens.","Configurar permissões.","Instalar visuais."],c:0,e:"No Model View visualizam-se e gerem-se os relacionamentos entre tabelas."},
  {sec:"Power BI — Interface",lvl:"III",k:"i-campos-areas",q:"Ao construir um gráfico, os campos arrastam-se para áreas como:",opts:["Valores, Eixos e Legendas.","Colunas, Índices e Chaves.","Norte, Sul e Este.","Cabeçalho e Rodapé."],c:0,e:"No painel de Campos da visualização há áreas de Valores, Eixos e Legendas."},
  {sec:"Power BI — Interface",lvl:"III",k:"i-filtro-visual",q:"Os filtros de VISUALIZAÇÃO afetam:",opts:["Todas as páginas.","Apenas o visual selecionado.","Todo o relatório.","O Service."],c:1,e:"O filtro de visualização afeta apenas o visual selecionado."},
  {sec:"Power BI — Interface",lvl:"I",k:"i-design",q:"A Área de Design (no painel de relatórios) é onde:",opts:["Se arrastam e organizam gráficos e visuais.","Se configura a rede.","Se instala o Power BI.","Se define a password."],c:0,e:"É o espaço principal onde se compõem as visualizações do relatório."},
  {sec:"Power BI — Interface",lvl:"II",k:"i-exibicao",q:"A guia 'Exibição' (View) controla:",opts:["Temas, visualização móvel e layout.","Relacionamentos.","Publicação.","Fontes de dados."],c:0,e:"A guia Exibição gere temas, vista móvel e ajustes de layout."},

  /* ============ Conexão & Power Query ============ */
  {sec:"Conexão & Power Query",lvl:"I",k:"c-obterdados",q:"Para começar a trabalhar com dados no Power BI usa-se:",opts:["'Obter Dados' (Get Data).","'Publicar'.","'Fechar e Aplicar'.","'Nova Medida'."],c:0,e:"'Obter Dados' abre a janela com as fontes disponíveis."},
  {sec:"Conexão & Power Query",lvl:"I",k:"c-fontes",q:"São exemplos de fontes de dados do Power BI:",opts:["Excel, CSV, SQL Server, APIs e serviços na nuvem.","Apenas ficheiros Word.","Apenas imagens.","Apenas e-mails."],c:0,e:"Suporta ficheiros, bases de dados, serviços online/nuvem e APIs."},
  {sec:"Conexão & Power Query",lvl:"I",k:"c-pq",q:"O Power Query serve para:",opts:["Criar dashboards.","Extrair, transformar e preparar dados (ETL) com interface visual.","Escrever medidas DAX.","Publicar relatórios."],c:1,e:"O Power Query é o ETL do Power BI, sem necessidade de programação avançada."},
  {sec:"Conexão & Power Query",lvl:"I",k:"c-etl-sigla",q:"ETL significa:",opts:["Extract, Transform, Load.","Edit, Test, Launch.","Export, Table, List.","Extract, Transfer, Link."],c:0,e:"Extract (extrair), Transform (transformar) e Load (carregar)."},
  {sec:"Conexão & Power Query",lvl:"I",k:"c-fechar",q:"Para carregar os dados transformados no modelo usa-se:",opts:["'Fechar e Aplicar'.","'Publicar'.","'Guardar como'.","'Atualizar tudo'."],c:0,e:"'Fechar e Aplicar' carrega os dados transformados no modelo."},
  {sec:"Conexão & Power Query",lvl:"II",k:"c-nulos",q:"Para substituir valores nulos numa coluna usa-se:",opts:["'Substituir Valores'.","'Remover Duplicatas'.","'Anexar Consultas'.","'Publicar'."],c:0,e:"'Substituir Valores' troca nulos por um valor (ex.: 0 ou 'Desconhecido')."},
  {sec:"Conexão & Power Query",lvl:"II",k:"c-dup",q:"Para eliminar registos repetidos usa-se:",opts:["'Remover Duplicatas'.","'Alterar Tipo'.","'Mesclar Consultas'.","'Dividir Coluna'."],c:0,e:"'Remover Duplicatas' elimina registos repetidos."},
  {sec:"Conexão & Power Query",lvl:"II",k:"c-tipo",q:"Um número lido como texto corrige-se com:",opts:["'Alterar Tipo'.","'Remover Linhas'.","'Anexar Consultas'.","Ignorando."],c:0,e:"'Alterar Tipo' garante o tipo de dado correto por coluna."},
  {sec:"Conexão & Power Query",lvl:"II",k:"c-filtrar",q:"Para filtrar linhas por critérios (datas, categorias) usa-se:",opts:["O ícone de filtro no cabeçalho da coluna.","'Anexar Consultas'.","Uma medida DAX.","'Publicar'."],c:0,e:"O ícone de filtro no topo da coluna permite incluir/excluir valores."},
  {sec:"Conexão & Power Query",lvl:"II",k:"c-coluna",q:"Para criar uma coluna com uma fórmula (ex.: margem) usa-se:",opts:["'Coluna Personalizada'.","'Remover Duplicatas'.","'Alterar Tipo'.","'Publicar'."],c:0,e:"'Coluna Personalizada' cria colunas por fórmula (ex.: ([Receita]-[Custo])/[Receita])."},
  {sec:"Conexão & Power Query",lvl:"II",k:"c-dividir",q:"Para separar 'Nome Completo' em nome e sobrenome usa-se:",opts:["'Dividir Coluna' (por delimitador).","'Combinar Colunas'.","'Alterar Tipo'.","'Remover Linhas'."],c:0,e:"'Dividir Coluna' divide por delimitador ou nº fixo de caracteres."},
  {sec:"Conexão & Power Query",lvl:"III",k:"c-mesclar",q:"'Mesclar Consultas' corresponde a:",opts:["Empilhar linhas.","Um JOIN entre tabelas por chave.","Remover duplicados.","Publicar."],c:1,e:"Mesclar = JOIN (combina colunas por chave); Anexar = empilhar linhas."},
  {sec:"Conexão & Power Query",lvl:"III",k:"c-anexar",q:"'Anexar Consultas' requer que as tabelas:",opts:["Tenham estruturas diferentes.","Tenham a mesma estrutura (mesmas colunas).","Estejam no Service.","Tenham uma linha."],c:1,e:"Anexar empilha registos de tabelas com a mesma estrutura."},
  {sec:"Conexão & Power Query",lvl:"III",k:"c-pasta",q:"Ao ligar a uma PASTA de ficheiros CSV iguais, o Power BI:",opts:["Lê só um ficheiro.","Combina automaticamente os dados de todos os ficheiros.","Apaga os ficheiros.","Converte em imagens."],c:1,e:"Combina automaticamente os dados de todos os ficheiros da pasta."},
  {sec:"Conexão & Power Query",lvl:"II",k:"c-import-dq",q:"Ao ligar a SQL Server, 'Importar' vs 'DirectQuery':",opts:["São iguais.","Importar carrega os dados; DirectQuery consulta a fonte em tempo real sem importar.","Importar é só para Excel.","DirectQuery copia para o OneDrive."],c:1,e:"Importar traz os dados; DirectQuery deixa-os na fonte (ideal para grandes volumes)."},
  {sec:"Conexão & Power Query",lvl:"III",k:"c-auth",q:"Uma causa comum de falha de ligação a fontes é:",opts:["Falha de autenticação (credenciais/OAuth incorretos ou permissões).","Excesso de cores.","Falta de gráficos.","Título em falta."],c:0,e:"Credenciais erradas, permissões insuficientes ou método de autenticação incorreto."},
  {sec:"Conexão & Power Query",lvl:"III",k:"c-porta",q:"Que porta o SQL Server usa por defeito?",opts:["80.","443.","1433.","21."],c:2,e:"O SQL Server usa a porta 1433 por defeito; o firewall tem de a permitir."},
  {sec:"Conexão & Power Query",lvl:"III",k:"c-gateway",q:"Para atualizar, no Service, dados de fontes locais é preciso:",opts:["Um Gateway de dados instalado e configurado.","Exportar CSV diário.","Uma app Viewer.","DirectQuery em tudo."],c:0,e:"Fontes locais exigem um gateway de dados corretamente configurado."},
  {sec:"Conexão & Power Query",lvl:"III",k:"c-limites",q:"Para lidar com limites de tamanho de dados, uma boa prática é:",opts:["Carregar tudo sempre.","Filtrar/agregar no Power Query e/ou usar DirectQuery.","Duplicar colunas.","Desligar a internet."],c:1,e:"Reduzir volume (filtrar/agregar) ou usar DirectQuery ajuda a respeitar limites."},
  {sec:"Conexão & Power Query",lvl:"II",k:"c-renomear",q:"No Power Query, renomear uma coluna faz-se:",opts:["Clicando duas vezes no nome da coluna.","Só no Excel.","Com DROP COLUMN.","Não é possível."],c:0,e:"Basta duplo-clique no nome (ou reorganizar arrastando)."},

  /* ============ Modelação de Dados ============ */
  {sec:"Modelação de Dados",lvl:"I",k:"m-modelo",q:"A função principal do modelo de dados é:",opts:["Criar gráficos.","Organizar tabelas e relacionamentos.","Publicar no Service.","Importar Excel."],c:1,e:"O modelo organiza tabelas e os seus relacionamentos."},
  {sec:"Modelação de Dados",lvl:"I",k:"m-star",q:"No Star Schema, a estrutura é:",opts:["Tudo em cadeia.","Tabela fato ao centro, dimensões à volta.","Uma tabela única.","Dimensões ao centro."],c:1,e:"A fato fica ao centro, ligada às dimensões em redor (estrela)."},
  {sec:"Modelação de Dados",lvl:"I",k:"m-fato",q:"A tabela FATO contém tipicamente:",opts:["Só texto.","Valores quantitativos (métricas) e chaves estrangeiras.","Só datas.","Cores."],c:1,e:"A fato regista eventos com valores agregáveis e chaves para as dimensões."},
  {sec:"Modelação de Dados",lvl:"I",k:"m-dim",q:"A tabela DIMENSÃO fornece:",opts:["Números para somar.","Informação descritiva que dá contexto aos factos.","Chaves de encriptação.","Ligações à net."],c:1,e:"As dimensões qualificam os factos com atributos descritivos."},
  {sec:"Modelação de Dados",lvl:"II",k:"m-fk",q:"As chaves estrangeiras que ligam factos e dimensões estão na:",opts:["Tabela fato.","Só nas dimensões.","No Service.","No Power Query."],c:0,e:"A tabela fato contém as chaves estrangeiras para as dimensões."},
  {sec:"Modelação de Dados",lvl:"II",k:"m-dim-tam",q:"As tabelas dimensão tendem a ter:",opts:["Muitas linhas, poucas colunas.","Menos linhas que a fato, mas muitas colunas descritivas.","Só uma coluna.","Só números."],c:1,e:"Menos linhas que os factos, mas muitas colunas descritivas."},
  {sec:"Modelação de Dados",lvl:"II",k:"m-1n",q:"O relacionamento mais comum no Power BI é:",opts:["Muitos-para-Muitos.","Um-para-Muitos (1:N).","Um-para-Um.","Nenhum."],c:1,e:"O 1:N é o mais comum: uma chave única liga a vários registos noutra tabela."},
  {sec:"Modelação de Dados",lvl:"II",k:"m-nn",q:"Produto fornecido por vários Fornecedores e vice-versa é um relacionamento:",opts:["Um-para-Um.","Um-para-Muitos.","Muitos-para-Muitos.","Sem relação."],c:2,e:"Múltiplas ocorrências de ambos os lados = Muitos-para-Muitos."},
  {sec:"Modelação de Dados",lvl:"II",k:"m-11",q:"Um relacionamento 1:1 ocorre quando:",opts:["Ambos os lados têm valores únicos.","Um lado repete.","Não há chave.","Há muitos valores dos dois lados."],c:0,e:"No 1:1 os dois lados têm valores únicos."},
  {sec:"Modelação de Dados",lvl:"II",k:"m-auto",q:"A deteção automática de relacionamentos ocorre quando:",opts:["As tabelas têm colunas com nomes semelhantes.","Não há colunas em comum.","Se publica no Service.","Se aplica formatação."],c:0,e:"O Power BI sugere relacionamentos ao detetar colunas de nomes semelhantes."},
  {sec:"Modelação de Dados",lvl:"II",k:"m-cardinalidade",q:"A cardinalidade de um relacionamento define-se:",opts:["Ao criar/editar o relacionamento.","Só no Service.","No Excel.","Não é configurável."],c:0,e:"Ao criar o relacionamento definem-se cardinalidade e direção do filtro."},
  {sec:"Modelação de Dados",lvl:"III",k:"m-filtro-uni",q:"Por defeito/para desempenho, a direção do filtro cruzado deve ser:",opts:["Bidirecional sempre.","Unidirecional (bidirecional só quando necessário).","Desativada.","Aleatória."],c:1,e:"O unidirecional reduz recursos; o bidirecional só quando necessário."},
  {sec:"Modelação de Dados",lvl:"III",k:"m-medida-perf",q:"Para desempenho, quando possível deve preferir-se:",opts:["Colunas calculadas.","Medidas (calculadas em runtime, não armazenadas).","Colunas de texto.","Tabelas duplicadas."],c:1,e:"As medidas calculam-se em tempo de execução, melhorando o desempenho."},
  {sec:"Modelação de Dados",lvl:"III",k:"m-coluna-calc",q:"Uma coluna calculada é:",opts:["Recalculada a cada filtro.","Calculada na atualização, linha a linha, e armazenada.","Só visual.","Igual a uma medida."],c:1,e:"A coluna calculada é computada por linha na atualização e fica armazenada."},
  {sec:"Modelação de Dados",lvl:"III",k:"m-star-vant",q:"Uma vantagem do Star Schema é:",opts:["Consultas mais rápidas e análise mais fácil.","Impedir novas dimensões.","Aumentar a complexidade.","Eliminar a fato."],c:0,e:"Estrutura simples: consultas rápidas, análise eficiente e escalabilidade."},
  {sec:"Modelação de Dados",lvl:"III",k:"m-granularidade",q:"A granularidade da tabela fato refere-se a:",opts:["O nível de detalhe de cada linha (ex.: cada linha = uma venda).","O nº de cores.","O nº de dimensões.","O tipo de gateway."],c:0,e:"Granularidade é o nível de detalhe de cada registo da fato."},

  /* ============ Relatórios & Visualizações ============ */
  {sec:"Relatórios & Visualizações",lvl:"I",k:"v-func",q:"A função principal do Power BI Desktop é:",opts:["Gerir e-mails.","Criar relatórios e dashboards interativos.","Editar imagens.","Programar macros."],c:1,e:"É o ambiente de criação de relatórios e visualizações interativas."},
  {sec:"Relatórios & Visualizações",lvl:"I",k:"v-arrastar",q:"Para criar uma visualização, no Power BI:",opts:["Arrastam-se campos do painel para a área de relatório.","Escreve-se código C#.","Instala-se um plugin obrigatório.","Publica-se primeiro."],c:0,e:"Arrastam-se os campos para a área e escolhe-se/ajusta-se o tipo de visual."},
  {sec:"Relatórios & Visualizações",lvl:"II",k:"v-appsource",q:"Visuais personalizados adicionais obtêm-se em:",opts:["AppSource ('Obter mais visuais').","Ficheiro > Guardar.","Power Query.","Só os nativos existem."],c:0,e:"Além dos nativos, há visuais da comunidade no AppSource."},
  {sec:"Relatórios & Visualizações",lvl:"II",k:"v-barra-coluna",q:"O gráfico de coluna (vertical) é preferível para:",opts:["Rótulos muito longos.","Dados com ordem temporal (anos, meses).","Percentagens de um todo.","Um único valor."],c:1,e:"Coluna (vertical) é bom para tempo; barra (horizontal) para rótulos longos."},
  {sec:"Relatórios & Visualizações",lvl:"II",k:"v-barra-uso",q:"O gráfico de barra (horizontal) é útil quando:",opts:["Há muitas categorias ou rótulos longos.","Se mostra evolução temporal.","Há só um dado.","Se quer uma pizza."],c:0,e:"A barra horizontal facilita a leitura de muitas categorias/rótulos longos."},
  {sec:"Relatórios & Visualizações",lvl:"II",k:"v-fc",q:"A formatação condicional permite:",opts:["Aplicar cores, ícones e barras com base em regras.","Publicar automaticamente.","Criar relacionamentos.","Instalar o gateway."],c:0,e:"Destaca valores segundo regras (cores, ícones, barras de dados)."},
  {sec:"Relatórios & Visualizações",lvl:"III",k:"v-fc-tipos",q:"Os três tipos principais de formatação condicional são:",opts:["Escala de cores, regras de valores e ícones.","Barras, linhas e pizza.","Import, DirectQuery e Live.","Viewer, Contributor e Admin."],c:0,e:"Escala de cores, regras de valores e conjuntos de ícones."},
  {sec:"Relatórios & Visualizações",lvl:"III",k:"v-fc-titulo",q:"A formatação condicional aplicada ao TÍTULO permite:",opts:["Tornar o título dinâmico com base nos dados (via 'fx').","Publicar o relatório.","Criar medidas.","Instalar visuais."],c:0,e:"Via 'fx' o título pode variar conforme os valores dos dados."},
  {sec:"Relatórios & Visualizações",lvl:"III",k:"v-marcadores",q:"Os 'Marcadores' (Bookmarks) permitem:",opts:["Criar medidas.","Guardar estados de filtros/visualizações para navegação personalizada.","Exportar PDF.","Ligar a bases na nuvem."],c:1,e:"Guardam o estado atual (filtros/visuais) para navegação personalizada."},
  {sec:"Relatórios & Visualizações",lvl:"I",k:"v-padrao",q:"Ao arrastar um campo, o Power BI cria:",opts:["Um erro.","Uma visualização padrão (ex.: tabela ou gráfico de barras) ajustável depois.","Uma medida DAX automática.","Um dashboard no Service."],c:1,e:"Cria um visual padrão que se pode depois alterar para outro tipo."},
  {sec:"Relatórios & Visualizações",lvl:"II",k:"v-alternar",q:"Para mudar o tipo de gráfico de um visual:",opts:["Seleciona-se outro tipo no painel Visualizações.","Reinstala-se o Power BI.","Só via Service.","Não é possível."],c:0,e:"Alterna-se o tipo no painel de Visualizações à direita."},
  {sec:"Relatórios & Visualizações",lvl:"III",k:"v-fc-passos",q:"Ao aplicar formatação condicional a uma tabela/matriz, começa-se por:",opts:["Selecionar a tabela/matriz e o campo a formatar.","Publicar no Service.","Instalar um visual.","Criar um relacionamento."],c:0,e:"Seleciona-se a visualização e o campo, depois escolhe-se o tipo de formatação."},
  {sec:"Relatórios & Visualizações",lvl:"I",k:"v-interativo",q:"Os relatórios do Power BI destacam-se por serem:",opts:["Estáticos e não editáveis.","Interativos (filtros e interações em tempo real).","Só em papel.","Só texto."],c:1,e:"São interativos, com filtros e interações em tempo real."},
  {sec:"Relatórios & Visualizações",lvl:"II",k:"v-coluna-uso",q:"Para análises de tendências ao longo do tempo, é adequado:",opts:["Gráfico de coluna.","Só uma tabela de texto.","Um slicer apenas.","Um cartão."],c:0,e:"O gráfico de coluna (vertical) é adequado para tendências temporais."},

  /* ============ DAX ============ */
  {sec:"DAX",lvl:"I",k:"d-def",q:"A DAX é:",opts:["Um tipo de gráfico.","Uma linguagem de fórmulas para cálculos e análise no Power BI.","Uma fonte de dados.","Um formato de ficheiro."],c:1,e:"DAX (Data Analysis Expressions) cria medidas, colunas calculadas e tabelas."},
  {sec:"DAX",lvl:"I",k:"d-sum",q:"Que função DAX soma os valores de uma coluna?",opts:["COUNT.","SUM.","ADD.","TOTAL."],c:1,e:"SUM() soma os valores de uma coluna."},
  {sec:"DAX",lvl:"I",k:"d-average",q:"Que função DAX calcula a média?",opts:["AVERAGE.","MEDIAN.","SUM.","MODE."],c:0,e:"AVERAGE() calcula a média aritmética."},
  {sec:"DAX",lvl:"I",k:"d-today",q:"Em DAX, a data atual obtém-se com:",opts:["GETDATE().","TODAY().","NOW().","DATE()."],c:1,e:"Em DAX usa-se TODAY() (GETDATE() é do T-SQL)."},
  {sec:"DAX",lvl:"I",k:"d-year",q:"Que função DAX extrai o ano de uma data?",opts:["YEAR().","DATEADD().","WEEKDAY().","EOMONTH()."],c:0,e:"YEAR() extrai o ano; MONTH() e DAY() o mês e o dia."},
  {sec:"DAX",lvl:"I",k:"d-if",q:"Que função lógica retorna um valor se verdadeiro e outro se falso?",opts:["SUM().","IF().","ALL().","RELATED()."],c:1,e:"IF() é a função lógica base."},
  {sec:"DAX",lvl:"I",k:"d-concat",q:"Que função DAX combina duas strings?",opts:["CONCATENATE().","SUM().","FILTER().","YEAR()."],c:0,e:"CONCATENATE() junta strings (ex.: nome + sobrenome)."},
  {sec:"DAX",lvl:"I",k:"d-counta",q:"A diferença entre COUNT e COUNTA é:",opts:["São iguais.","COUNT conta numéricos; COUNTA conta valores em geral.","COUNTA só datas.","COUNT soma."],c:1,e:"COUNT conta numéricos; COUNTA conta valores em geral."},
  {sec:"DAX",lvl:"II",k:"d-calculate",q:"A função CALCULATE serve para:",opts:["Criar texto.","Alterar/modificar o contexto de filtro de um cálculo.","Importar tabelas.","Definir relações."],c:1,e:"CALCULATE modifica o contexto aplicando filtros à expressão."},
  {sec:"DAX",lvl:"II",k:"d-related",q:"A função RELATED substitui que fórmula do Excel?",opts:["SOMA.","PROCV (VLOOKUP).","SE.","CONT.NÚM."],c:1,e:"RELATED acede a valores de tabela relacionada, como o PROCV."},
  {sec:"DAX",lvl:"II",k:"d-switch",q:"Que função avalia uma expressão contra vários valores (simplifica IF encadeados)?",opts:["FILTER.","SWITCH.","ALL.","RELATED."],c:1,e:"SWITCH simplifica múltiplos IF encadeados."},
  {sec:"DAX",lvl:"II",k:"d-filter",q:"A função FILTER devolve:",opts:["Altera o contexto do modelo.","Uma tabela filtrada por uma condição.","Uma soma.","Remove filtros."],c:1,e:"FILTER retorna uma tabela com as linhas que satisfazem a condição."},
  {sec:"DAX",lvl:"II",k:"d-andor",q:"As funções AND()/OR() servem para:",opts:["Combinar várias condições lógicas.","Somar colunas.","Ordenar tabelas.","Criar relacionamentos."],c:0,e:"Combinam várias condições lógicas."},
  {sec:"DAX",lvl:"II",k:"d-totalytd",q:"A função TOTALYTD calcula:",opts:["O acumulado do ano (Year-To-Date).","A diferença entre datas.","A média mensal.","O total de todos os anos."],c:0,e:"TOTALYTD acumula o ano; há também TOTALQTD e TOTALMTD."},
  {sec:"DAX",lvl:"II",k:"d-agg-fam",q:"SUM, AVERAGE e COUNT pertencem à família de:",opts:["Funções de agregação.","Funções de texto.","Funções de data.","Funções relacionais."],c:0,e:"São funções de agregação."},
  {sec:"DAX",lvl:"III",k:"d-calc-filter",q:"Diferença entre CALCULATE e FILTER:",opts:["CALCULATE altera o contexto de filtro; FILTER devolve uma tabela filtrada.","FILTER altera o contexto; CALCULATE devolve tabela.","Não há diferença.","Ambas somam."],c:0,e:"CALCULATE modifica o contexto; FILTER retorna uma tabela filtrada."},
  {sec:"DAX",lvl:"III",k:"d-all",q:"A função ALL() faz:",opts:["Soma tudo.","Remove todos os filtros de uma tabela/coluna.","Conta únicos.","Ordena."],c:1,e:"ALL() remove filtros, muito usada com CALCULATE."},
  {sec:"DAX",lvl:"III",k:"d-sameperiod",q:"Qual função devolve o mesmo período do ano anterior?",opts:["TOTALYTD().","SAMEPERIODLASTYEAR().","TODAY().","DATEDIFF()."],c:1,e:"SAMEPERIODLASTYEAR() serve para comparações homólogas."},
  {sec:"DAX",lvl:"III",k:"d-rankx",q:"A função RANKX serve para:",opts:["Ordenar colunas por nome.","Classificar (ranking) valores segundo uma expressão.","Contar únicos.","Devolver o maior valor."],c:1,e:"RANKX atribui um ranking aos valores segundo uma expressão."},
  {sec:"DAX",lvl:"III",k:"d-col-medida",q:"Sobre coluna calculada vs medida:",opts:["Ambas armazenam o valor.","A coluna calculada armazena (linha a linha); a medida calcula sob demanda (runtime).","A medida é sempre mais lenta.","A coluna é dinâmica."],c:1,e:"Coluna calculada é armazenada; medida é dinâmica, conforme o contexto."},

  /* ============ Publicar & Dashboards ============ */
  {sec:"Publicar & Dashboards",lvl:"I",k:"pub-publicar",q:"Após 'Publicar' no Power BI Desktop, o relatório fica:",opts:["No PC, na pasta do PBIX.","Num Workspace no Power BI Service.","Numa App pública automática.","No OneDrive por defeito."],c:1,e:"Publicar envia o relatório para um workspace no Power BI Service."},
  {sec:"Publicar & Dashboards",lvl:"I",k:"pub-service",q:"O Power BI Service é:",opts:["Uma app offline.","A plataforma na nuvem para publicar, partilhar e colaborar.","Um editor de imagens.","Uma base local."],c:1,e:"É o serviço online onde os relatórios são publicados e partilhados."},
  {sec:"Publicar & Dashboards",lvl:"I",k:"pub-dashdef",q:"Um dashboard no Power BI é:",opts:["Um ficheiro Excel.","Uma tela única que reúne visualizações (fixadas) de um ou vários relatórios.","Uma medida DAX.","Uma tabela do Power Query."],c:1,e:"Reúne visualizações relevantes numa só tela para monitorização rápida."},
  {sec:"Publicar & Dashboards",lvl:"I",k:"pub-pin",q:"Para adicionar uma visualização a um dashboard usa-se:",opts:["O ícone de alfinete (fixar/pin).","Exportar PDF.","Arrastar para o ambiente de trabalho.","Escrever DAX."],c:0,e:"No Service 'fixa-se' (pin) uma visualização para a colocar no dashboard."},
  {sec:"Publicar & Dashboards",lvl:"II",k:"pub-login",q:"Ao publicar, é normalmente pedido:",opts:["O login com conta Microsoft/Office 365.","Um cartão de crédito.","Um antivírus.","Um código de barras."],c:0,e:"A publicação pede autenticação com a conta do Service (Office 365)."},
  {sec:"Publicar & Dashboards",lvl:"II",k:"pub-workspace",q:"Os Workspaces são:",opts:["Ficheiros locais.","Áreas colaborativas onde equipas criam/publicam/gerem relatórios e dashboards.","Um tipo de gráfico.","Uma função DAX."],c:1,e:"Áreas colaborativas; ao publicar aí, os membros acedem conforme permissões."},
  {sec:"Publicar & Dashboards",lvl:"II",k:"pub-link",q:"Para partilhar por link, os destinatários precisam de:",opts:["Ter permissões de acesso ao workspace.","Instalar o Desktop.","Ser administradores.","Ter o ficheiro PBIX."],c:0,e:"O link só funciona com permissões adequadas ao workspace."},
  {sec:"Publicar & Dashboards",lvl:"II",k:"pub-viewer",q:"Que permissão permite APENAS visualizar?",opts:["Administrador.","Contribuidor.","Visualizador (Viewer).","Proprietário."],c:2,e:"Visualizador só vê; Contribuidor edita; Administrador gere permissões."},
  {sec:"Publicar & Dashboards",lvl:"II",k:"pub-contrib",q:"A permissão 'Contribuidor' permite:",opts:["Só visualizar.","Editar o relatório.","Nada.","Só exportar."],c:1,e:"O Contribuidor pode editar o relatório."},
  {sec:"Publicar & Dashboards",lvl:"III",k:"pub-admin",q:"Que nível pode gerir permissões, editar e visualizar?",opts:["Visualizador.","Contribuidor.","Administrador.","Convidado."],c:2,e:"O Administrador gere permissões, edita e visualiza."},
  {sec:"Publicar & Dashboards",lvl:"III",k:"pub-gateway",q:"O Gateway de dados é necessário para:",opts:["Criar gráficos no Desktop.","Atualizar, a partir do Service, dados de fontes locais.","Instalar o Power BI.","Definir cores."],c:1,e:"Relatórios no Service que usam fontes locais precisam de gateway para atualizar."},
  {sec:"Publicar & Dashboards",lvl:"III",k:"pub-agendada",q:"Onde se configura a atualização agendada de um conjunto de dados?",opts:["No Desktop, em Modelação.","Na página do relatório em Editar.","Nas definições do conjunto de dados no serviço.","Apenas no Gateway."],c:2,e:"Define-se nas definições (settings) do dataset no Power BI Service."},
  {sec:"Publicar & Dashboards",lvl:"III",k:"pub-directquery",q:"Que modo consulta a fonte em tempo real sem importar os dados?",opts:["Importar.","DirectQuery.","Live Excel.","Offline."],c:1,e:"No DirectQuery os dados ficam na fonte e são consultados em tempo real."},
  {sec:"Publicar & Dashboards",lvl:"III",k:"pub-export-seg",q:"Que medida de segurança o Power BI oferece com dados confidenciais?",opts:["Definir quem pode exportar os dados do relatório.","Encriptar o ecrã.","Bloquear o rato.","Desligar a internet."],c:0,e:"Permite controlar quem pode exportar os dados — importante para confidencialidade."},
  {sec:"Publicar & Dashboards",lvl:"I",k:"pub-dashvsrel",q:"Diferença entre relatório e dashboard:",opts:["São iguais.","O relatório pode ter várias páginas; o dashboard é uma tela única com visuais fixados.","O dashboard só tem texto.","O relatório só existe no telemóvel."],c:1,e:"Relatório = várias páginas; dashboard = tela única com visuais fixados de um ou mais relatórios."},
  {sec:"Publicar & Dashboards",lvl:"II",k:"pub-colaboracao",q:"O Power BI Service permite, em tempo real:",opts:["Compilar código.","Partilha e colaboração em relatórios/dashboards.","Editar vídeo.","Gerir impressoras."],c:1,e:"O Service possibilita partilha e colaboração em tempo real."}

